-- Password values must be salted password hashes generated by the backend.
CREATE TABLE IF NOT EXISTS public.users (
    user_id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_username varchar(64) NOT NULL UNIQUE,
    user_password varchar(255) NOT NULL,
    account_created timestamptz NOT NULL DEFAULT now()
);

-- A backend using the Supabase service role bypasses RLS. Do not expose that
-- service role key to clients. Enable RLS to prevent accidental public access.
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

